content.text:
{
  "name": "WebDAV网络存储",
  "name_en": "WebDAV Network Storage",
  "manufacturer": "",
  "description": "通过 WebDAV 提供文件与目录访问的网络存储系统，可用于实验数据、显微图像和分析结果的集中保存、浏览与共享。",
  "description_en": "A network storage system that exposes files and directories over WebDAV, used in laboratories for centralized storage, browsing, and sharing of experimental data, microscopy images, and analysis results.",
  "tag_hints": [
    "WebDAV",
    "network storage",
    "file sharing",
    "lab data management",
    "directory browsing",
    "experimental data storage"
  ],
  "actions": [
    {
      "action_name": "auto-getProperties",
      "description": "获取该存储目录的属性信息。",
      "description_en": "Get the properties of this storage directory."
    },
    {
      "action_name": "auto-getMembers",
      "description": "获取该目录下的直接成员列表。",
      "description_en": "Get the list of immediate members in this directory."
    },
    {
      "action_name": "auto-rootdir",
      "description": "获取 WebDAV 根目录信息。",
      "description_en": "Get the WebDAV root directory information."
    },
    {
      "action_name": "auto-findMember",
      "description": "查找指定的文件或子目录成员。",
      "description_en": "Find a specified file or subdirectory member."
    },
    {
      "action_name": "auto-sendData",
      "description": "发送该目录的内容给客户端。",
      "description_en": "Send the contents of this directory to the client."
    },
    {
      "action_name": "auto-recvMember",
      "description": "接收并保存上传到该目录的成员文件。",
      "description_en": "Receive and save a member file uploaded into this directory."
    }
  ]
}

